 raw,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};var s Spec;if json.Unmarshal(raw,&s)!=nil{panic("spec")};u,e:=url.Parse(s.Base);if e!=nil||u.Scheme!="http"||u.Hostname()!="127.0.0.1"||u.User!=nil||u.Path!=""{panic("loopback only")};host,_,e:=net.SplitHostPort(s.TLSAddr);if e!=nil||host!="127.0.0.1"{panic("loopback TLS only")};var cat struct{Checks []Check `json:"checks"`};if json.Unmarshal(s.Catalog,&cat)!=nil{panic("catalog")};var payload map[string]any;json.Unmarshal(s.Catalog,&payload)
 roots:=x509.NewCertPool();if !roots.AppendCertsFromPEM([]byte(s.CA)){panic("CA")};cfg:=&tls.Config{RootCAs:roots,MinVersion:tls.VersionTLS12,ServerName:"127.0.0.1"};client:=&http.Client{Timeout:2*time.Second,Transport:&http.Transport{MaxConnsPerHost:8,MaxIdleConnsPerHost:8,DisableCompression:true},CheckRedirect:func(r *http.Request,v []*http.Request)error{return http.ErrUseLastResponse}}
